[Form]
public class METTransferOrderExtractScreen extends FormRun
{
    METTransferOrderExtractScreenParameters     metTransferOrderExtractScreenParameters;
    METTransferorderExtractScreenProcessor      metTransferOrderExtractScreenProcessor;
    METTransferOrderExtractScreenTmp            extractScreenTmp;
    Map                                         selectionMap;
    Args                                        args;

    boolean                                     selectAll;    

    [FormObservable]
    METTotalPallets                             totalPallets,totalActualPallets;    
    #SysSystemDefinedButtons
    FormCommandButtonControl                    editbutton;
    #Task


}

    /// <summary>
    /// Enable or disable buttons based on records selection
    /// </summary>
    public void enableOrDisableButtons()
    {
        boolean isExtracted         = metTransferOrderExtractScreenParameters.parmExtracted() == METOrderExtractStatus::Extracted;
        boolean isSelectionEmpty    = selectionMap.empty();
        boolean checkPicklist       = this.checkMarkedOrdersPicklist();

        boolean anyProcessing = false;
        if (!isSelectionEmpty)
        {
            InventTransferTable inventTransferTableLoc;
            METInventTransferTableExt metInventTransferTableExtLoc;
            MapEnumerator mapEnum = selectionMap.getEnumerator();
            while (mapEnum.moveNext())
            {
                select firstonly RecId from inventTransferTableLoc
                    where inventTransferTableLoc.RecId == mapEnum.currentKey()
                    join Processing from metInventTransferTableExtLoc
                        where metInventTransferTableExtLoc.InventTransferTable == inventTransferTableLoc.RecId;
                if (metInventTransferTableExtLoc.Processing == NoYes::Yes)
                {
                    anyProcessing = true;
                    break;
                }
            }
        }

        // Enable or disable controls based on selection status
        METransferOrderExtractScreenModifyDialog.enabled(!isSelectionEmpty && checkPicklist);
        Calculate.enabled(!isSelectionEmpty);
        UpdateStatusFormButtonControl.enabled(!isSelectionEmpty);
        METTransferPickingListGeneration.enabled(!isSelectionEmpty && !isExtracted && !anyProcessing);        
    }

