    public void refreshSummaryControls(container _container)
    {
        SumOfOrderedCases.value(conPeek(_container, 1));
        SumOfEstimatedCases.value(conPeek(_container, 2));

        SumOfOrderedVolume.realValue(conPeek(_container, 3));
        SumOfEstimatedVolume.realValue(conPeek(_container, 4));

        SumOfOrderedlWeight.realValue(conPeek(_container, 5));
        SumOfEstimatedlWeight.realValue(conPeek(_container, 6));
            
        SumOfOrderedBrokenCases.value(conPeek(_container, 7));
        SumOfEstimatedBrokenCases.value(conPeek(_container, 8));
    }

    /// <summary>
    /// Populates the <c>METOrderExtractScreenTmp</c> table.
    /// </summary>
    public void populateOrders()
    {
        delete_from extractScreenTmp;

        totalPallets        = 0;
        totalActualPallets  = 0;

        if (this.args().parmObject() == null)
        {
            metTransferOrderExtractScreenParameters = METTransferOrderExtractScreenParameters::construct();
        }
        else
        {
            metTransferOrderExtractScreenParameters = this.args().parmObject() as METTransferOrderExtractScreenParameters;
        }
                
        metTransferOrderExtractScreenParameters.loadLastValue(formStr(METTransferOrderExtractScreen));

        boolean  isExtracted = metTransferOrderExtractScreenParameters.parmExtracted() != METOrderExtractStatus::Extracted;

        if (isExtracted)
        {
            boolean isEnabled       = !selectionMap.empty();
            boolean checkPicklist   = this.checkMarkedOrdersPicklist();
            
            METransferOrderExtractScreenModifyDialog.enabled(isEnabled && checkPicklist);
            METTransferPickingListGeneration.enabled(isEnabled);
        }

        metTransferOrderExtractScreenProcessor = metTransferOrderExtractScreenProcessor::construct(metTransferOrderExtractScreenParameters);

        extractScreenTmp = metTransferOrderExtractScreenProcessor.populateOrderExtractScreen();
        METTransferOrderExtractScreenTmp.linkPhysicalTableInstance(extractScreenTmp);

        //CS - CB715_TranferOrderExtract - PS
        if (metTransferOrderExtractScreenProcessor)
        {
            metTransferOrderExtractScreenProcessor.parmMETTransferOrderExtractScreenParams(metTransferOrderExtractScreenParameters);
            container ret = metTransferOrderExtractScreenProcessor.calculate(METTransferOrderExtractScreenTmp);
            element.refreshSummaryControls(ret);
            //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
            if (metTransferOrderExtractScreenProcessor.parmTransferOrderRecordsFound())
            {
                METFormActionPaneTabControl.enabled(true);
                editbutton.enabled(true);
            }
            else
            {
                METFormActionPaneTabControl.enabled(false);
                editbutton.enabled(false);
            }
            //Bug 229712 CB628 - Update status in extraction screen got refresh issue -end
            METTransferOrderExtractScreenTmp_ds.research(true);
            
        }
        //CE - CB715_TranferOrderExtract - PS
        InventTransferTable_ds.executeQuery();

    }

/// <summary>
