}

    /// <summary>
    /// Form initialise
    /// </summary>
    public void init()
    {
        super();

        selectionMap = new Map(Types::Int64, Types::String);
        OrderExtractGrid.footerShown(true);

        //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
        editbutton  = this.control(this.controlId(#SystemDefinedViewEditButton)) as FormCommandButtonControl;
        editbutton.enabled(false);
        //Bug 229712 CB628 - Update status in extraction screen got refresh issue -end
    }

    /// <summary>
    /// Returns true when none of the marked orders have an associated picklist.
    /// If any marked order has a picklist number (i.e. a WMS picking route/line exists for the SalesId),
    /// this returns false.
    /// </summary>
    /// <returns>true if none of the marked orders have a picklist; otherwise, false.</returns>
    private boolean checkMarkedOrdersPicklist()
    {
        str                         transferId;
        str                         picklistNumber;
        MapEnumerator               mapEnumerator = selectionMap.getEnumerator();
        METInventTransferTableExt   inventTransferTableExt;

        if (selectionMap.empty())
        {
            return false;
        }

        while (mapEnumerator.moveNext())
        {
            transferId              = mapEnumerator.currentValue();
            inventTransferTableExt  = METInventTransferTableExt::findByTransferId(transferId);

            picklistNumber = METInventTransferTableExt::getLastPickListInfo(inventTransferTableExt).pickingRouteID;

            if (picklistNumber)
            {
                return false;
            }
        }

        // No picklists found for any marked orders -> UpdateStatus can be enabled
        return true;
    }

