        /// <summary>
        /// Select all records in the grid
        /// </summary>
        public void clicked()
        {
            QueryRun qr = InventTransferTable_ds.queryRun();
            qr.reset();

            while (qr.next())
            {
                InventTransferTable inventTransferTableLoc = qr.get(tableNum(InventTransferTable));
                METInventTransferTableExt metInventTransferTableExtLoc = inventTransferTableLoc.metInventTransferTableExt();

                if(metInventTransferTableExtLoc.OrderExtractStatus != METOrderExtractStatus::Extracted)
                {
                    if(!selectionMap.exists(inventTransferTableLoc.RecId))
                    {
                        selectionMap.insert(inventTransferTableLoc.RecId, inventTransferTableLoc.TransferId);
                        selectAll = true;
                        if (metInventTransferTableExtLoc.Processing == NoYes::Yes)
                        {
                            warning(strFmt("@MET:METOrderExtractingWarning", inventTransferTableLoc.TransferId));
                        }
                    }
                }
                else
                {
                    if(selectionMap.exists(inventTransferTableLoc.RecId))
                    {
                        selectionMap.remove(inventTransferTableLoc.RecId);
                    }
                }

            }
           
            InventTransferTable_ds.refresh();
            element.enableOrDisableButtons();
            element.task(#taskRefresh);
            selectAll = false;
        }

